    onSuccess: (saved) => {
      queryClient.setQueryData(plansQueryKey(sheet ?? ''), saved);
    },
  });
  const submit = useSubmitOnce(toggle);
  const rowAction = useRowAction(`person-${person.id}`);
  const take = (action: 'pause' | 'resume') => { rowAction.take(); submit(action); };
  return (
